"""Chat-turn boundary detector for layer 15, MLP down_proj, component 4097.

On ordinary text this component is near 0 (its small noise is not predictable from
the token). It goes strongly negative on the chat template's turn structure:

- the role word right after <|im_start|>: "assistant" about -21, "user" about -15
  (only about -6 in the first ~20 tokens of a document);
- the newline after that role word (about -7.5), or after <|im_end|> (about -6.3),
  or after <tool_call> / <tool_response> (about -7);
- the turn and document end markers: <|endoftext|> about -6.5, and <|im_end|> about
  -5.5, or -9.5 when it follows sentence punctuation;
- a short tail of weaker negatives 3 to 9 tokens after <|im_start|> (about -2.5), and
  '{"' right after a newline (about -4.5, the start of a JSON tool argument).

<|im_start|> itself is slightly positive (+1.2). The first token of each document
is 0, since attention and positions restart there.

Everything is read from the prefix: the newest token, the one before it, and the
last chat marker in the same document with how many tokens ago it was.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

MARKERS = ("<|im_start|>", "<|im_end|>", "<|endoftext|>")
SENTENCE_END = (".", "!", "?", "。", "！", "？")
TOOL_TAGS = ("<tool_call>", "<tool_response>")
ROLE_VALUE = {"assistant": -21.0, "user": -15.0}
SHORT_DOC_USER = -6.0  # "user" role word within the first 20 tokens of a document
SHORT_DOC_TOKENS = 20


def value(tok, prev, marker, offset, doc_pos):
    """Activation of the token `tok`, given the previous token, the last chat marker,
    how many tokens after that marker `tok` is, and its position in the document."""
    if doc_pos == 0:
        return 0.0
    if tok == "<|im_start|>":
        return 1.2
    if tok == "<|endoftext|>":
        return -6.5
    if tok == "<|im_end|>":
        return -9.5 if prev in SENTENCE_END else -5.5
    if marker == "<|im_start|>":
        if offset == 1:
            if tok == "user" and doc_pos < SHORT_DOC_TOKENS:
                return SHORT_DOC_USER
            return ROLE_VALUE.get(tok, 0.0)
        if offset == 2 and tok == "\n":
            return -7.5
        if 3 <= offset <= 9:
            return -2.5
    if marker == "<|im_end|>" and offset == 1 and tok == "\n":
        return -6.3
    if tok == "\n" and prev in TOOL_TAGS:
        return -7.0
    if tok == '{"' and prev == "\n":
        return -4.5
    return 0.0


def step(carry, prefix, upstream: Mapping):
    t = prefix.position
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "start": t, "marker": None, "offset": 0}
    prev = prefix.token_strings[-2] if t > carry["start"] else None
    marker, offset = carry["marker"], carry["offset"]
    if tok in MARKERS:
        marker, offset = tok, 0
        result = value(tok, prev, None, 0, t - carry["start"])
    else:
        if marker is not None:
            offset += 1
        result = value(tok, prev, marker, offset, t - carry["start"])
    new = {"doc": doc, "start": carry["start"], "marker": marker, "offset": offset}
    return new, float(result)

"""Comparison and predicate frames: a rare, strong negative dip on the word that opens a
predicate after "like", "as", "is", "become" and their Chinese counterparts.

What the component does, in plain terms: its activation is mostly a dense, context-dependent
signal that no simple rule captures. Its large negative values (down to about -30) sit on
the word that comes right before the model says what something is *like*: the article in
"like [a] ...", the copula or article in "... is [like] ...", "is [a] ...", "become [a] ...",
and the Chinese comparison and link words 如 / 像 / 如同 / 就像 / 宛如 / 好像 (like, as) and
是 / 为 (is). Right after "like", an article is the strongest case.

This program predicts those negative values from the two words before each position and 0
everywhere else. It needs no state beyond the current document's previous token.
"""

from collections.abc import Mapping

READS = ()

ARTICLES = {" a", " an", " the"}
COPULAS = {" is", " are", " was", " were", " be", " been", " become", " becoming", " getting"}
COMPARES = {" like", " as"}
CHINESE_COMPARES = {"如", "像", "如同", "就像", "宛如", "好像", "似"}
CHINESE_LINKS = {"是", "为"}


def step(carry, prefix, upstream: Mapping):
    t = prefix.position
    word = prefix.token_strings[t]
    same_doc = t > 0 and prefix.document_ids[t - 1] == prefix.document_ids[t]
    prev = prefix.token_strings[t - 1] if same_doc else ""
    if word in ARTICLES and prev == " like":
        value = -1.7
    elif (word in ARTICLES | COPULAS | COMPARES) and (prev in COPULAS | COMPARES):
        value = -0.4
    elif word in CHINESE_COMPARES:
        value = -2.3
    elif word in CHINESE_LINKS:
        value = -0.7
    else:
        value = 0.0
    return carry, value

"""Layer-15 MLP unit 4104 (this component), read from the token text.

It is mostly quiet in prose. Inside code it swings both ways, and the swing
is biggest in deeply nested blocks. The rules below capture the tendencies
we could find: indentation that opens the body of a block is pushed negative,
the sign of diff-marker lines, and a few null/ternary tokens."""

import re

READS = ()

NULLS = {"nil", "null", "NULL", "None", "nullptr"}
HEADER = re.compile(r"\b(if|while|for|switch|elif)\b")


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    t = prefix.position
    new_doc = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc or carry is None:
        carry = {"depth": 0, "opener": False, "line_start": True, "header": False}
    st = carry
    indent = re.fullmatch(r"[ \t]+", s) is not None
    width = len(s.expandtabs(4)) if indent else 0
    value = 0.0
    if indent and st["line_start"]:
        if st["opener"]:
            value = -1.5 if width >= 9 else -0.5
        elif width >= 9 and st["depth"] >= 1:
            value = -0.3
    elif st["line_start"] and s[:1] == "+":
        value = 0.8
    elif st["line_start"] and s[:1] == "-":
        value = -0.4
    elif st["header"] and s.strip() in NULLS:
        value = 0.3
    elif s.strip() == "?":
        value = -0.3
    # update the state with this token
    st = dict(st)
    for piece in re.split(r"(\n)", s):
        if piece == "\n":
            st["line_start"] = True
            st["header"] = False
            continue
        if piece == "":
            continue
        st["depth"] = max(0, st["depth"] + piece.count("{") - piece.count("}"))
        if st["line_start"] and piece.strip():
            st["opener"] = False
        st["line_start"] = False
        if HEADER.search(piece):
            st["header"] = True
        if st["header"] and re.search(r"[{:;]", piece):
            st["header"] = False
    st["opener"] = s.rstrip(" \t").endswith(("{\n", ":\n")) or (
        st["opener"] and s.strip() == "" and "\n" not in s
    )
    return st, float(value)

"""Layer 15 MLP hidden unit 4108 (component 4108 of layers.15.mlp.down_proj).

Plain-language reading: the unit goes negative inside a noun phrase whose head
noun has not arrived yet. It dips on the article "the", most of all when it
follows a preposition or a verb of place or inclusion ("at the", "from the",
"including the"), and it dips on an adjective or adverb that follows a
determiner or intensifier ("the smaller", "the more common", "very large").
It leans slightly positive on "of". It is zero at the first token of a
document. Most of its variance is not captured by any such word rule.
"""
from wordnet import parts_of_speech

READS = ()

DETERMINERS = {"the", "a", "an", "this", "that", "these", "those", "its", "their",
               "his", "her", "our", "my", "your", "every", "each", "some", "any"}
INTENSIFIERS = {"more", "most", "very", "much", "so", "too", "really", "quite",
                "rather", "less", "least", "many", "few"}
PREPOSITIONS = {"of", "in", "on", "at", "to", "for", "from", "with", "by", "into",
                "than", "as", "about", "over", "under", "between", "through",
                "including", "like", "against", "until", "via", "beyond", "include"}


def _word(s):
    return s.strip().lower()


def _is_modifier(w):
    """An adjective or adverb by WordNet, and not also a noun."""
    if not w.isalpha():
        return False
    p = parts_of_speech(w)
    return bool(p) and ("adjective" in p or "adverb" in p) and "noun" not in p


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    word = _word(prefix.token_strings[-1])
    prev = _word(prefix.token_strings[-2])
    if prev in DETERMINERS | INTENSIFIERS and _is_modifier(word):
        value = -0.35
    elif word == "the":
        value = -0.5 if prev in PREPOSITIONS else -0.1
    elif word == "of":
        value = 0.1
    else:
        value = 0.0
    return carry, value

"""Names in source code (layer 15 MLP, component 4111).

The component is near zero on most text. It rises on the tokens that spell out
a programming name (a variable, function, class or type identifier), and more
so the more code surrounds them. It is strongest on the first name right after
a declaration keyword such as `def`, `fn`, `const`, `void`, `class`, or a type
like `String` or `int`, and it is raised for names inside quotes. Underscores
and capital letters in a name add a little.
"""
import re

READS = ()

NAME = re.compile(r"\s?[A-Za-z_][A-Za-z0-9_]*")
CODE_MARK = re.compile(r"[{};()=<>\[\]]|->|::|\.\w|\n\s+")
DECL = {
    "fn", "def", "const", "void", "String", "int", "class", "var", "let",
    "mut", "function", "double", "float", "bool", "char", "struct", "enum",
    "public", "private", "static", "long",
}


def code_density(prefix):
    """Share of the last 48 tokens of this document that look like code."""
    t = prefix.position
    docs = prefix.document_ids
    start = max(0, t - 47)
    while start < t and docs[start] != docs[t]:
        start += 1
    window = prefix.token_strings[start:t]
    if not window:
        return 0.0
    return sum(1 for w in window if CODE_MARK.search(w)) / len(window)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    if not NAME.fullmatch(word):
        return carry, 0.0
    density = code_density(prefix)
    value = 0.1 + 2.0 * min(density, 0.5)
    if prefix.position > 0:
        before = prefix.token_strings[-2]
        if before.strip() in DECL:
            value += 3.0 if density >= 0.1 else 1.0
        if before.endswith(('"', "'")):
            value += 1.0
    if "_" in word:
        value += 0.7
    if re.search(r"[A-Z]", word):
        value += 0.3
    return carry, float(value)

"""Coordinating conjunctions: a detector for "and" (and its translations) that joins list items or clauses.

The component's activation is large and positive on the word "and" (and "und", "и", "et", "&", "y",
"e" in other languages). It is strongest when "and" follows a comma or the close of a list item
("X, Y, and Z", "...), and ..."), and weaker when "and" joins two words directly ("long and tedious").
The disjunction "or" is the opposite: negative, except after a comma. Commas are mildly negative.
Everything else is near zero; the remaining variance is diffuse and not captured by a token rule.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

AND_WORDS = {"and", "And", "AND"}
OTHER_CONJUNCTIONS = {"und", "и", "et", "&", "y", "e", "dan", "و"}
OR_WORDS = {"or", "или", "ó", "oder", "ou", "lub"}
LIST_BOUNDARIES = {",", ";", ")", "),", '"', "”", "]"}


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip() if same_doc else ""
    after_boundary = before in LIST_BOUNDARIES or before.isdigit()
    if word in AND_WORDS:
        return carry, 2.8 if after_boundary else 1.4
    if word in OTHER_CONJUNCTIONS:
        return carry, 1.0
    if word in OR_WORDS:
        return carry, 0.4 if before == "," else -0.5
    if word == ",":
        return carry, -0.1
    return carry, 0.0

"""Age and time-span detector for layers.15.mlp.down_proj component 4124.

The component writes toward age words: its output promotes "age", "aged", "young",
"elderly", "years", "adulthood". Its activation is positive where the text is about
ages, school grades, career stages or spans of time, and it is largest just before a
number or an age is written:
- on the age and time words themselves ("age", "young", "years", "school", "career");
- on the digits (and the space before them) of an age after "age", "aged", "grade" or
  "under" ("at age [ ]18");
- on "of", "to", "in", "the" after a time word ("age [of]", "end [of]", "period [of]");
- on "his/her/their" after a milestone verb ("completed [his] residency").
Most of its variance is diffuse and not captured: everything else predicts the component's
mean, 0.09 (a document's first token predicts 0).
"""
READS = ()
BASELINE = 0.09  # the component's mean activation

AGE_WORDS = {"age", "ages", "aged", "young", "younger", "old", "older", "elderly", "adult",
             "adults", "child", "children", "school", "college", "grade", "career", "early",
             "middle", "late", "retired", "years", "year", "-year", "months", "senior",
             "student", "students", "graduate", "graduated", "infant", "teen", "baby"}
AGE_LEAD = {"age", "aged", "ages", "grade", "under"}
TIME_LEAD = {"age", "years", "year", "period", "term", "end", "stage", "duration", "prior",
             "during", "school", "months", "days", "time", "rest", "beginning", "part"}
MILESTONE = {"completed", "obtained", "earned", "finished", "graduated", "served", "pursued",
             "received", "began", "started", "joined", "attended", "entered", "retired",
             "spent", "during", "after"}
POSSESSIVE = {"his", "her", "their"}
LINKERS = {"of"}
NUMBER_WORDS = {"one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
                "first", "second", "third", "last"}


def _word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    if len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0  # a document's first token sits at 0
    words = [_word(s) for s in prefix.token_strings]
    cur = words[-1]
    earlier = [w for w in words[:-1] if w]  # non-blank words before this token
    last = earlier[-1] if earlier else ""
    if cur == "" or cur.isdigit():
        # a number, or the space before one, right after an age phrase: "age 1[8]"
        lead = next((w for w in reversed(earlier) if not w.isdigit()), "")
        if lead in AGE_LEAD:
            return None, 4.0
    if cur in AGE_WORDS:
        return None, 2.1
    if cur in LINKERS and last in TIME_LEAD:
        return None, 2.0
    if cur in POSSESSIVE and any(w in MILESTONE for w in earlier[-3:]):
        return None, 2.4
    if cur in NUMBER_WORDS:
        return None, 0.45
    return None, BASELINE

"""Introducer tokens: a component of layer 15's MLP down projection that is large on tokens
which open something still to come.

Its activation is near zero on most tokens, and clearly positive on a small set of them:

- a colon, before a list, a quotation or an explanation ("the following:", "said:",
  "is:", ":\\n\\n" before bullets);
- a dash or an ellipsis ("—", "…", "...");
- a correlative word that expects its partner ("either" ... "or", "both" ... "and"),
  or "following";
- an opening quotation mark.

The program predicts a fixed strength on those tokens and zero elsewhere. It reads only the
newest token, so it keeps no state. It explains about 6% of the variance: the activation's
large values also occur on many other tokens, in diffuse contexts this program does not model.
"""

READS = ()

COLON = {":", ":\n", ":\n\n", ":\n\n\n", ":\\", "：", "：\n\n", "：“"}
DASH_ELLIPSIS = {"—", "…", "…\n", "……", "...", "...\n", "...\n\n", " …", " ...", " ...\n", "...."}
CORRELATIVE = {" either", " both", " neither", " following"}
OPEN_QUOTE = {" “", " ‘", " „", " «", "“", "「"}
INTRODUCERS = COLON | DASH_ELLIPSIS | CORRELATIVE | OPEN_QUOTE

STRENGTH = 2.0
"""The mean activation on introducer tokens in the training rows, about 1.9 to 2.2 by class."""


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    return carry, STRENGTH if token in INTRODUCERS else 0.0

"""Layer 15 MLP down_proj, component 4149: a weak, mostly-negative "coordination ahead" signal.

What it does: its output direction, when the activation is negative, pushes the next-token
logits toward coordinating conjunctions ("and", "or", "&", "und", "和", "и"...). So it is
most negative where a pair or list is being set up and the model expects "and"/"or" next:
after "both", "either", "between", on contrast words such as "upper", "left", "first",
on digits and on single-letter labels. Everywhere else it sits near zero.

This program writes that pattern as a few word-class rules and returns a small number per
token. It explains only a little of the variance: the activation is spread over many
tokens and is not well predicted by the current word or the one before it.
"""

READS = ()

# Words that open a pair or a contrast: "both X and Y", "either X or Y", "between X and Y".
PAIR_WORDS = {"both", "either", "neither", "between"}
# Words that come in opposed or ordered pairs: "upper and lower", "left or right", "first and second".
CONTRAST_WORDS = {
    "upper", "lower", "left", "right", "front", "back", "top", "bottom", "first", "second",
    "positive", "negative", "maximum", "minimum", "high", "low", "inner", "outer",
}
CONJUNCTIONS = {"and", "or", "&"}


def step(carry, prefix, upstream):
    if prefix.position == 0:
        return carry, 0.0  # each row's first token: the component is silent
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower()
    value = -0.04
    if word.isdigit() and len(word) == 1:
        value -= 0.13  # a single digit
    if word in CONJUNCTIONS:
        value -= 0.12
    if word in CONTRAST_WORDS:
        value -= 0.45
    if word in PAIR_WORDS:
        value -= 0.08
    if before in PAIR_WORDS:
        value -= 0.46  # the first item of "both X and ...", "between X and ..."
    if before in CONTRAST_WORDS:
        value -= 0.08
    return carry, value

"""Layer 15 MLP down_proj, component 4152: a "be-verb waiting for its predicate" detector.

The component fires on the English verb "to be" (is, are, was, were, be, been, being,
're, 'm). Its strength depends on what the be-verb is about to take:

- After a modal or have/has/had ("can be", "must be", "has been"), and for was, were,
  been, it is strong: the sentence is heading for a predicate, usually a passive past
  participle ("was built", "is used", "can be done").
- Other be-verbs after a subject are moderately strong.
- Where the be-verb opens a question ("Is it ...?") or an existential or deictic
  sentence ("there is", "here is", "this is", "what is") it is weak.
- A negation or adverb placed straight after a be-verb ("is not", "was also",
  "is often") is moderately strong too.
- All other tokens are 0.

The values are the typical activation levels in each case, not fitted to a table.
"""

READS = ()

BE = {"is", "are", "was", "were", "be", "been", "being", "'re", "'m"}
EXISTENTIAL = {"there", "here", "this", "what", "so", "why", "how"}
MODAL_OR_HAVE = {"can", "cannot", "may", "shall", "could", "must", "should", "will",
                 "might", "would", "has", "have", "had"}
PAST_FORMS = {"was", "were", "been"}
ADVERB_OR_NOT = {"not", "also", "often", "still", "always", "typically", "originally",
                 "then", "now", "actually", "specifically", "never", "just", "only",
                 "already", "usually", "generally", "sometimes"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip()
    word = raw.lower()
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        before = ""
    else:
        before = prefix.token_strings[-2].strip().lower()
    if word in BE:
        if raw[:1].isupper() and before not in MODAL_OR_HAVE:
            return carry, 2.0  # a capitalised be-verb opens a question: "Is it ...?"
        if before in EXISTENTIAL:
            return carry, 3.0
        if before in MODAL_OR_HAVE or word in PAST_FORMS:
            return carry, 8.0
        return carry, 6.0
    if before in BE and word in ADVERB_OR_NOT:
        return carry, 5.0
    return carry, 0.0

"""Rough predictor for layers.15.mlp.down_proj:4156.

This component is a diffuse, weak direction: its activation has mean ~0.02 and
spread ~0.26 and is not tied to any clear token or context concept. The best
simple description found is a few per-class averages on the current token:

- the first token of a document is always ~0;
- the next three tokens (document positions 1-3) sit below average (about -0.045);
- otherwise the value depends weakly on the token's character class: word
  continuations and word starts without a leading space are a little higher,
  Cyrillic and punctuation higher still, and a leading-space word lowest.

Those averages explain only about 0.1% of the activation's variance on held-out
rows; a per-token lookup table would add roughly 1-2%, but is not a concept.
"""
import re

READS = ()

EARLY = -0.045  # document positions 1-3
CLASS_MEAN = {
    "cyr": 0.055,
    "word": 0.035,
    "punct": 0.033,
    "other": 0.028,
    "han": 0.026,
    "space": 0.021,
    "newline": 0.021,
    "digit": 0.019,
    "word_sp": 0.008,
}


def char_class(s):
    if "\n" in s:
        return "newline"
    if s.strip() == "":
        return "space"
    if re.search(r"[一-鿿]", s):
        return "han"
    if re.search(r"[Ѐ-ӿ]", s):
        return "cyr"
    if re.fullmatch(r"\s?[A-Za-z]+", s):
        return "word_sp" if s[0] == " " else "word"
    if re.fullmatch(r"\s?\d+", s):
        return "digit"
    if re.fullmatch(r"\s?[^\w\s]+", s):
        return "punct"
    return "other"


def step(carry, prefix, upstream):
    # carry: (document label of the previous token, position within its document)
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos = 0
    else:
        pos = carry[1] + 1
    if pos == 0:
        value = 0.0
    elif pos <= 3:
        value = EARLY
    else:
        value = CLASS_MEAN[char_class(prefix.token_strings[-1])]
    return (doc, pos), value
